@@ -12,17 +12,29 @@ import crypto from "node:crypto";
 const algorithm = "sha256";
+const signatureCache = new Map<string, boolean>();

 export function verifyGitHubSignature(input: {
   rawBody: Buffer;
   signatureHeader: string | undefined;
   secret: string;
 }) {
   if (!input.signatureHeader) {
     return false;
   }
+
+  const cached = signatureCache.get(input.signatureHeader);
+  if (cached !== undefined) {
+    return cached;
+  }

   const expected =
     "sha256=" +
     crypto
       .createHmac(algorithm, input.secret)
       .update(input.rawBody)
       .digest("hex");

-  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(input.signatureHeader));
+  const valid = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(input.signatureHeader));
+  signatureCache.set(input.signatureHeader, valid);
+  return valid;
 }
